const fruits = ['Apple', 'Banana', 'Cherry'];

function FruitList() {
  return (
    <ul>
      {fruits.map((fruit) => (
        <li key={fruit}>{fruit}</li>
      ))}
    </ul>
  );
}

const tasks = [
  { id: 101, title: 'Write lesson', done: true },
  { id: 102, title: 'Review quiz', done: false },
  { id: 103, title: 'Publish', done: false },
];

function TaskList({ showDone }) {
  const visible = showDone ? tasks : tasks.filter((task) => !task.done);

  return (
    <ol>
      {visible.map((task) => (
        <li key={task.id} className={task.done ? 'done' : undefined}>
          {task.title}
        </li>
      ))}
    </ol>
  );
}

import { useState } from 'react';

function Guest({ name }) {
  const [confirmed, setConfirmed] = useState(false);
  return (
    <li>
      {name}
      <button onClick={() => setConfirmed(true)}>{confirmed ? 'Confirmed' : 'Confirm'}</button>
    </li>
  );
}

function Guests({ guests }) {
  return (
    <ul>
      {guests.map((guest, index) => (
        <Guest key={index} name={guest} />
      ))}
    </ul>
  );
}

function Leaderboard({ players }) {
  const ranked = [...players].sort((a, b) => b.score - a.score);

  return (
    <ol>
      {ranked.map((player) => (
        <li key={player.id}>{player.name} – {player.score}</li>
      ))}
    </ol>
  );
}

import { Fragment } from 'react';

function Glossary({ terms }) {
  if (terms.length === 0) return <p>No terms yet.</p>;

  return (
    <dl>
      {terms.map((term) => (
        <Fragment key={term.word}>
          <dt>{term.word}</dt>
          <dd>{term.meaning}</dd>
        </Fragment>
      ))}
    </dl>
  );
}
